import csv
import io
import unittest

from stock import export_rows


class ExportTest(unittest.TestCase):
    def test_round_trip(self):
        text = export_rows([("Blue", 2)])
        self.assertEqual(list(csv.reader(io.StringIO(text))), [
            ["name", "count"], ["Blue", "2"],
        ])
